// The Web Analytics query for the last 24 hours. The site tag is the `token` of Cloudflare's
// beacon (public, but account-specific); the import fills it in from SOPS, so it is not in the repository.
const until = $now.toUTC();
const since = until.minus({ hours: 24 });
const window = { datetime_geq: since.toISO(), datetime_leq: until.toISO() };
const query = `query($account: String!, $site: String!, $since: Time!, $until: Time!) {
  viewer { accounts(filter: { accountTag: $account }) {
    totals: rumPageloadEventsAdaptiveGroups(limit: 1,
      filter: { siteTag: $site, datetime_geq: $since, datetime_leq: $until }) { count sum { visits } }
    referrers: rumPageloadEventsAdaptiveGroups(limit: 10, orderBy: [count_DESC],
      filter: { siteTag: $site, datetime_geq: $since, datetime_leq: $until }) { count dimensions { refererHost } }
  } }
}`;
return [{ json: { graphql: { query, variables: {
  account: '76967f5ede1ce50efce34d90b7e94958', site: 'RESOLVE_SALE_DIGEST_SITE_TAG',
  since: window.datetime_geq, until: window.datetime_leq } } } }];

// Builds the Spanish digest email (HTML, with a plain-text fallback) from the three answers. A step
// that failed is named in its own section instead of stopping the email: a digest that says
// "No disponible" is better than no digest. Every value that comes from the data is escaped: the ids
// and sources reach Analytics Engine from a public endpoint.
const SITE = 'https://leaving-denver.pages.dev';
const MIN_VIEWS = 5; // many views and no text taps: the price is the likely reason (make reprice)
const TOP_ROWS = 5;
const SOURCE_LABELS = {
  flyer: 'Flyer', facebook: 'Facebook', craigslist: 'Craigslist', nextdoor: 'Nextdoor', offerup: 'OfferUp',
  activebuilding: 'ActiveBuilding', carscom: 'Cars.com', instagram: 'Instagram', whatsapp: 'WhatsApp',
  share: 'Compartido', other: 'Otros', direct: 'Directo',
};
const EVENTS_DOWN = 'la consulta a Analytics Engine falló (ver la ejecución en n8n)';
const WEB_ERRORS = 'la consulta a Web Analytics devolvió errores (ver la ejecución en n8n)';
const WEB_EMPTY = 'la consulta a Web Analytics no devolvió datos (revisa el site tag y el token, ver el runbook)';

const rowsOf = name => {
  const json = $(name).first().json;
  return Array.isArray(json.data) ? json.data.map(r => ({ ...r, n: Number(r.n) || 0 })) : null;
};
const recent = rowsOf('Events, last 24 h');
const sale = rowsOf('Events, whole sale');
const webJson = $('Web Analytics, last 24 h').first().json;

const esc = value => String(value).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
const humanize = id => {
  const words = String(id).replace(/[-_]+/g, ' ').trim().slice(0, 80);
  return words.charAt(0).toUpperCase() + words.slice(1);
};
const plural = (n, one, many) => `${n} ${n === 1 ? one : many}`;
const num = n => (n === null ? '—' : String(n));
const byCountThenName = (a, b) => b[1] - a[1] || (a[0] < b[0] ? -1 : 1);
const sum = (rows, event) => rows.filter(r => r.event === event).reduce((total, r) => total + r.n, 0);
// A Map, not an object: an id such as `constructor` must be a key, not a property lookup.
const count = (counts, key, n) => counts.set(key, (counts.get(key) || 0) + n);
const tally = (rows, event, key) => {
  const counts = new Map();
  rows.filter(r => r.event === event && r[key]).forEach(r => count(counts, r[key], r.n));
  return [...counts].sort(byCountThenName);
};
const pairs = list => list.map(([name, n]) => `${name} ${n}`).join(' · ');

// Web Analytics: GraphQL answers 200 with `errors`, sometimes beside partial data: do not print those figures.
const readWeb = () => {
  if (Array.isArray(webJson.errors) && webJson.errors.length) return { down: WEB_ERRORS };
  const groups = (((webJson.data || {}).viewer || {}).accounts || [])[0];
  if (!groups) return { down: WEB_EMPTY };
  const totals = Array.isArray(groups.totals) ? groups.totals[0] : null;
  const counts = new Map();
  (groups.referrers || []).forEach(g => count(counts, ((g.dimensions || {}).refererHost) || 'Directo', Number(g.count) || 0));
  return {
    visits: totals ? Number((totals.sum || {}).visits) || 0 : 0,
    pages: totals ? Number(totals.count) || 0 : 0,
    referrers: [...counts].sort(byCountThenName).slice(0, TOP_ROWS),
  };
};
const web = readWeb();

const topRows = rows => {
  const views = new Map(tally(rows, 'view_item', 'item'));
  const taps = new Map(tally(rows, 'text_tap', 'item'));
  const items = [...new Set([...views.keys(), ...taps.keys()])]
    .map(id => ({ id, views: views.get(id) || 0, taps: taps.get(id) || 0 }))
    .sort((a, b) => b.views - a.views || b.taps - a.taps || (a.id < b.id ? -1 : 1))
    .slice(0, TOP_ROWS)
    .map(i => ({ label: humanize(i.id), url: `${SITE}/i/${encodeURIComponent(i.id)}/`, views: i.views, taps: i.taps }));
  const packs = tally(rows, 'text_tap', 'bundle').slice(0, TOP_ROWS)
    .map(([name, n]) => ({ label: `Pack: ${humanize(name)}`, url: null, views: null, taps: n }));
  return [...items, ...packs];
};
const sourceLabel = ([source, n]) => [SOURCE_LABELS.hasOwnProperty(source) ? SOURCE_LABELS[source] : humanize(source), n];
const sourcePairs = rows => tally(rows, 'visit', 'source').map(sourceLabel).sort(byCountThenName);

// Plain-text and HTML renderings of one section's body, side by side so they cannot drift apart.
const FONT = "-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif";
const MONO = "ui-monospace,SFMono-Regular,Menlo,Consolas,monospace";
const INK = '#1f2937', MUTED = '#6b7280', LINE = '#e5e7eb', ACCENT = '#0f766e', ACCENT_BG = '#ecfdf5';
const muted = html => `<div style="font-size:13px;line-height:1.5;color:${MUTED}">${html}</div>`;
const down = reason => ({ html: muted(`No disponible: ${esc(reason)}`), text: [`  No disponible: ${reason}`] });
const section = (title, body) => ({
  html: `<tr><td style="padding:22px 24px 0"><div style="font-size:12px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;color:${MUTED};padding-bottom:8px">${esc(title)}</div>${body.html}</td></tr>`,
  text: ['', title, ...body.text],
});

const tile = (label, value, small, accent) => {
  const box = accent ? `background:${ACCENT_BG};border:1px solid ${ACCENT}` : `background:#f9fafb;border:1px solid ${LINE}`;
  const color = accent ? ACCENT : INK;
  return `<td width="33%" valign="top" style="${box};border-radius:8px;padding:12px 10px;text-align:center">`
    + `<div style="font-size:12px;color:${accent ? ACCENT : MUTED};font-weight:${accent ? 700 : 400}">${esc(label)}</div>`
    + `<div style="font-size:30px;line-height:1.2;font-weight:700;color:${color}">${esc(value)}</div>`
    + `<div style="font-size:12px;color:${MUTED}">${esc(small)}</div></td>`;
};

const recentSum = event => (recent ? sum(recent, event) : null);
const saleSum = event => (sale ? sum(sale, event) : null);
const visitsSmall = web.down ? 'No disponible' : plural(web.pages, 'página vista', 'páginas vistas');
const kpis = [
  ['Visitas web', web.down ? null : web.visits, visitsSmall, false],
  ['Fichas abiertas', recentSum('view_item'), `total: ${num(saleSum('view_item'))}`, false],
  ['Mensajes', recentSum('text_tap'), `total: ${num(saleSum('text_tap'))}`, true],
];
const kpiSection = {
  html: `<tr><td style="padding:20px 18px 0"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:separate;border-spacing:6px 0"><tr>`
    + kpis.map(([label, value, small, accent]) => tile(label, num(value), small, accent)).join('') + '</tr></table></td></tr>',
  text: ['', ...kpis.map(([label, value, small]) => `${label}: ${num(value)} (${small})`)],
};

const cell = (n, extra = '') => `<td align="right" style="padding:7px 0 7px 12px;border-bottom:1px solid ${LINE};font-size:14px;${n ? extra : `color:${MUTED};`}">${n ? n : '–'}</td>`;
const headCell = (label, align) => `<td align="${align}" style="padding:0 0 6px 12px;font-size:12px;color:${MUTED}">${label}</td>`;
const itemsBody = () => {
  if (!recent) return down(EVENTS_DOWN);
  const rows = topRows(recent);
  if (!rows.length) return { html: muted('Nadie abrió fichas ayer.'), text: ['  Nadie abrió fichas ayer.'] };
  const html = `<table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr><td style="padding:0 0 6px 0;font-size:12px;color:${MUTED}">Artículo</td>${headCell('Vistas', 'right')}${headCell('Mensajes', 'right')}</tr>`
    + rows.map(r => {
      const name = esc(r.label);
      const link = r.url ? `<a href="${esc(r.url)}" style="color:${INK};text-decoration:none;border-bottom:1px dotted ${MUTED}">${name}</a>` : name;
      return `<tr><td style="padding:7px 0;border-bottom:1px solid ${LINE};font-size:14px;color:${INK}">${link}</td>${cell(r.views)}${cell(r.taps, `color:${ACCENT};font-weight:700;`)}</tr>`;
    }).join('') + '</table>';
  const text = rows.map(r => `  - ${r.label}: ${[r.views === null ? null : plural(r.views, 'vista', 'vistas'), r.taps ? plural(r.taps, 'mensaje', 'mensajes') : null].filter(Boolean).join(', ')}`);
  return { html, text };
};

const sourcesBody = () => {
  const line = (label, list, reason) => {
    const content = reason ? `No disponible: ${reason}` : list;
    return { html: `<div style="font-size:14px;line-height:1.7;color:${reason ? MUTED : INK}"><span style="color:${MUTED}">${label}:</span> ${esc(content)}</div>`, text: `  ${label}: ${content}` };
  };
  const lines = [];
  if (!recent) lines.push(line('Enlaces', '', EVENTS_DOWN));
  else if (sourcePairs(recent).length) lines.push(line('Enlaces', pairs(sourcePairs(recent))));
  else lines.push({ html: muted('Sin visitas por enlace.'), text: '  Sin visitas por enlace.' });
  lines.push(web.down ? line('Web Analytics', '', web.down) : line('Web Analytics', web.referrers.length ? pairs(web.referrers) : 'sin visitas'));
  return { html: lines.map(l => l.html).join(''), text: lines.map(l => l.text) };
};

const repriceBody = () => {
  if (!sale) return down(EVENTS_DOWN);
  const tapped = new Set(tally(sale, 'text_tap', 'item').map(([item]) => item));
  const found = tally(sale, 'view_item', 'item').filter(([item, n]) => n >= MIN_VIEWS && !tapped.has(item));
  if (!found.length) return null;
  const hint = id => `make reprice ID=${id} PRICE=<usd>`;
  const intro = 'Muchas vistas y ningún mensaje en toda la venta: quizá el precio es alto.';
  return {
    html: muted(esc(intro)) + found.map(([id, n]) => `<div style="padding:8px 0 0;font-size:14px;color:${INK}">${esc(humanize(id))} <span style="color:${MUTED}">· ${esc(plural(n, 'vista', 'vistas'))}, sin mensajes</span>`
      + `<div style="font-family:${MONO};font-size:12px;color:${MUTED}">${esc(hint(id))}</div></div>`).join(''),
    text: [`  ${intro}`, ...found.flatMap(([id, n]) => [`  - ${humanize(id)}: ${plural(n, 'vista', 'vistas')}, sin mensajes`, `    ${hint(id)}`])],
  };
};

const totals = sale
  ? `Toda la venta: ${plural(sum(sale, 'visit'), 'visita por enlace', 'visitas por enlace')} · ${plural(sum(sale, 'view_item'), 'ficha', 'fichas')} · ${plural(sum(sale, 'text_tap'), 'mensaje', 'mensajes')}.`
  : 'Toda la venta: no disponible.';
const footer = `${totals} Se cuentan eventos, no personas.`;

const when = $now.setZone('America/Denver').setLocale('es');
const longDate = when.toFormat("cccc d 'de' LLLL");
const title = 'Resumen de la venta';

const parts = [];
const visits = web.down ? (recent ? sum(recent, 'visit') : null) : web.visits;
if (visits !== null) parts.push(plural(visits, 'visita', 'visitas'));
if (recent) parts.push(plural(sum(recent, 'view_item'), 'ficha', 'fichas'), plural(sum(recent, 'text_tap'), 'mensaje', 'mensajes'));
const incomplete = parts.length > 0 && (!recent || !sale || web.down) ? ' (datos incompletos)' : '';
const subject = `Venta · ${when.toFormat('ccc d LLL')} — ${parts.length ? parts.join(', ') : 'sin datos'}${incomplete}`;

const sections = [
  kpiSection,
  section('Qué se mira (24 h)', itemsBody()),
  section('De dónde llegan (24 h)', sourcesBody()),
];
const reprice = repriceBody();
if (reprice) sections.push(section('Revisar precio', reprice));

const capitalized = longDate.charAt(0).toUpperCase() + longDate.slice(1);
const html = `<!DOCTYPE html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(subject)}</title></head>`
  + `<body style="margin:0;padding:0;background:#f4f4f5"><table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f4f4f5"><tr><td align="center" style="padding:16px 8px">`
  + `<table role="presentation" width="560" cellpadding="0" cellspacing="0" style="width:100%;max-width:560px;background:#ffffff;border:1px solid ${LINE};border-radius:10px;font-family:${FONT};color:${INK}">`
  + `<tr><td style="padding:24px 24px 0"><div style="font-size:22px;font-weight:700;color:${INK}">${esc(title)}</div><div style="font-size:14px;color:${MUTED}">${esc(capitalized)}</div></td></tr>`
  + sections.map(s => s.html).join('')
  + `<tr><td style="padding:22px 24px 20px"><div style="border-top:1px solid ${LINE};padding-top:12px;font-size:12px;line-height:1.5;color:${MUTED}">${esc(footer)}</div></td></tr>`
  + '</table></td></tr></table></body></html>';
const text = [title, capitalized, ...sections.flatMap(s => s.text), '', footer].join('\n');
return [{ json: { subject, html, text } }];
